APP_CSS = r"""
<style>
@import url('https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/static/pretendard.css');
:root{--blue:#2563EB;--blue2:#1D4ED8;--soft:#EFF6FF;--ink:#172033;--muted:#667085;--bg:#F7F9FC;--line:#E4EAF2;--green:#16A36A;--greens:#ECFDF3;--amber:#D97706;--ambers:#FFF8E7;--card:#FFFFFF}
html,body,[class*="css"]{font-family:'Pretendard',-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif}
#MainMenu,footer{visibility:hidden}
header[data-testid="stHeader"]{background:transparent!important;height:2.25rem!important;visibility:visible!important}
[data-testid="stSidebarCollapsedControl"],[data-testid="collapsedControl"]{visibility:visible!important;display:flex!important}
.stApp{background:var(--bg)}
.block-container{max-width:1320px;padding-top:.6rem!important;padding-bottom:1.2rem!important;padding-left:1.25rem!important;padding-right:1.25rem!important}
[data-testid="stSidebar"]{background:#FBFCFE!important;border-right:1px solid var(--line);min-width:290px!important;max-width:310px!important}
[data-testid="stSidebar"]>div:first-child{padding-top:.65rem!important}
[data-testid="stSidebar"] *{letter-spacing:-.01em}
[data-testid="stSidebar"] label,[data-testid="stSidebar"] p,[data-testid="stSidebar"] .stCaption{color:#475467!important;font-size:.84rem!important}
[data-testid="stSidebar"] hr{border-color:var(--line);margin:.7rem 0!important}
[data-testid="stSidebar"] [data-testid="stWidgetLabel"]{margin-bottom:.18rem!important}
[data-testid="stSidebar"] [data-baseweb="select"]>div,[data-testid="stSidebar"] input{min-height:38px!important;font-size:.87rem!important}
[data-testid="stFileUploaderDropzone"],[data-testid="stFileUploadDropzone"]{background:#fff!important;border:1px dashed #B8C7DD!important;border-radius:10px!important;min-height:76px!important;padding:.65rem!important}
[data-testid="stFileUploaderDropzone"] *,[data-testid="stFileUploadDropzone"] *{color:#344054!important;fill:#344054!important}
div.stButton>button,div.stDownloadButton>button{background:var(--blue)!important;color:#fff!important;border:1px solid var(--blue)!important;border-radius:8px!important;min-height:39px!important;font-weight:750!important;font-size:.86rem!important;transition:.12s ease}
div.stButton>button *,div.stButton>button p,div.stButton>button span,div.stDownloadButton>button *,div.stDownloadButton>button p,div.stDownloadButton>button span{color:#fff!important}
div.stButton>button:hover,div.stDownloadButton>button:hover{background:var(--blue2)!important;border-color:var(--blue2)!important}
div.stDownloadButton>button{width:100%}
.app-head{display:flex;justify-content:space-between;gap:14px;align-items:center;margin-bottom:10px;padding:4px 0 10px;border-bottom:1px solid var(--line)}
.app-brand{display:flex;gap:10px;align-items:center}.app-logo{width:38px;height:38px;border-radius:10px;background:linear-gradient(135deg,#2F6FED,#5B8DF6);display:flex;align-items:center;justify-content:center;color:#fff;font-size:20px;font-weight:800;box-shadow:0 4px 10px rgba(37,99,235,.14)}
.app-title{font-size:1.32rem;font-weight:800;color:var(--ink);letter-spacing:-.035em}.app-sub{font-size:.82rem;color:var(--muted);margin-top:2px}.live-chip{background:#fff;border:1px solid var(--line);border-radius:999px;padding:6px 10px;font-size:.77rem;color:#475467;white-space:nowrap}
.sidebar-brand{font-size:1rem;font-weight:800;color:var(--ink);margin:2px 0 11px}.side-section{font-size:.84rem;font-weight:800;color:#344054;margin:2px 0 6px}.side-gap{margin-top:13px!important}.side-help{font-size:.75rem;color:#667085;line-height:1.45;margin-top:4px}.developer-note{font-size:.78rem;line-height:1.45;color:#667085;background:#fff;border:1px solid var(--line);border-radius:9px;padding:9px 10px;margin:7px 0 2px}.developer-note b{color:#344054;font-size:.8rem}
.section-title{font-size:.98rem;font-weight:800;color:var(--ink);margin:14px 0 7px}.compact-title{margin-top:9px!important}.card-title{font-size:.96rem;font-weight:800;color:var(--ink);margin-bottom:4px}.card-desc{font-size:.81rem;color:var(--muted);line-height:1.45;margin-bottom:8px}.card-desc.no-margin{margin-bottom:0!important}
[data-testid="stVerticalBlockBorderWrapper"]{border-color:var(--line)!important;border-radius:10px!important;background:#fff!important;box-shadow:0 1px 2px rgba(16,24,40,.02)}
[data-testid="stVerticalBlockBorderWrapper"]>div{padding:.78rem .9rem!important}
.mini-info{font-size:.84rem;line-height:1.6;color:#475467;background:#F8FAFD;border:1px solid var(--line);border-radius:8px;padding:9px 11px}.mini-info b{color:var(--ink);margin-left:5px}.mini-label{display:inline-block;min-width:62px;color:var(--muted);font-size:.76rem}.upload-guide{min-height:76px;display:flex;flex-direction:column;justify-content:center}
.mini-status{font-size:.79rem;line-height:1.4;border-radius:8px;padding:8px 10px;min-height:38px}.warn-mini{background:var(--ambers);border:1px solid #F5D99A;color:#9A6700}.ok-mini{background:var(--greens);border:1px solid #B9EACF;color:#087A50}
.kpi-row{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin:9px 0 10px}.kpi-card{background:#fff;border:1px solid var(--line);border-radius:10px;padding:11px 13px;box-shadow:0 1px 2px rgba(16,24,40,.02)}.kpi-label{font-size:.76rem;color:var(--muted);font-weight:650;margin-bottom:4px}.kpi-value{font-size:1.34rem;font-weight:800;color:var(--ink);letter-spacing:-.035em;line-height:1.2}.kpi-unit{font-size:.8rem;color:var(--muted);font-weight:600;margin-left:2px}.kpi-note{font-size:.74rem;color:var(--muted);margin-top:3px}.small-value{font-size:.98rem!important;padding-top:3px}.compact-kpi{margin-top:0!important;margin-bottom:8px!important}
.work-card,.download-card,.mode-banner,.empty-card,.info-panel,.region-card{background:#fff;border:1px solid var(--line);border-radius:10px}.work-card{padding:12px 14px;margin-bottom:9px}.work-title{font-size:.92rem;font-weight:800;color:var(--ink);margin-bottom:3px}.work-desc{font-size:.8rem;color:var(--muted);line-height:1.45}.status{display:inline-flex;align-items:center;border-radius:999px;padding:4px 9px;font-size:.76rem;font-weight:750}.status.ok{background:var(--greens);color:var(--green)}.status.warn{background:var(--ambers);color:var(--amber)}
.download-card{display:flex;gap:9px;align-items:flex-start;padding:11px 13px;margin-bottom:6px;min-height:68px}.download-icon{width:34px;height:34px;flex:0 0 34px;border-radius:9px;background:var(--soft);display:flex;align-items:center;justify-content:center;font-size:17px;color:var(--blue);font-weight:800}.final-card{margin-top:9px}.mode-banner{padding:13px 15px;margin-bottom:9px}.mode-eyebrow{font-size:.74rem;color:var(--blue);font-weight:800;margin-bottom:2px}.mode-title{font-size:1.04rem;color:var(--ink);font-weight:800}.mode-desc{font-size:.8rem;color:var(--muted);margin-top:3px}.info-panel{display:flex;gap:9px;padding:12px 13px;min-height:78px}.info-icon{width:30px;height:30px;flex:0 0 30px;border-radius:9px;background:var(--greens);color:var(--green);display:flex;align-items:center;justify-content:center;font-weight:800}.empty-card{text-align:center;padding:24px 16px;margin-top:8px}.compact-empty{padding:19px 14px!important}.empty-icon{font-size:1.45rem;margin-bottom:5px;color:var(--blue)}
.small-file-icon{width:38px;height:38px;border-radius:10px;background:var(--soft);border:1px solid #D8E5FB;color:var(--blue);display:flex;align-items:center;justify-content:center;font-size:18px;font-weight:850;margin:1px auto}.small-file-icon.green-file{background:var(--greens);border-color:#C7EED8;color:var(--green)}.download-side-head{display:flex;align-items:center;gap:10px;margin-bottom:9px}.download-side-head .small-file-icon{margin:0}.file-name-box{font-size:.76rem;line-height:1.4;color:#475467;background:#F8FAFD;border:1px solid var(--line);border-radius:7px;padding:7px 8px;margin:7px 0 9px;word-break:break-all}
.region-card{padding:11px 13px;margin-top:8px}.compact-region{margin-top:6px!important}.region-track{height:7px;background:#EEF2F7;border-radius:999px;overflow:hidden;display:flex;margin:7px 0}.region-seg-1{background:#2563EB}.region-seg-2{background:#14B8A6}.region-seg-3{background:#CBD5E1}.region-legend{display:flex;gap:14px;flex-wrap:wrap;font-size:.76rem;color:var(--muted)}
.waiting-card{max-width:460px;margin:60px auto;background:#fff;border:1px solid var(--line);border-radius:14px;text-align:center;padding:28px}.waiting-icon{font-size:1.7rem}.waiting-title{font-size:1.05rem;font-weight:800;color:var(--ink);margin:7px 0 4px}.waiting-desc{font-size:.84rem;color:var(--muted)}.waiting-meta{font-size:.74rem;color:#98A2B3;margin-top:9px}
[data-testid="stAlert"]{padding:.6rem .75rem!important;font-size:.82rem!important;margin:.35rem 0!important}
[data-testid="stDataFrame"],[data-testid="stDataEditor"]{font-size:.8rem!important}
@media(max-width:1100px){.kpi-row{grid-template-columns:1fr 1fr}.block-container{padding-left:.8rem!important;padding-right:.8rem!important}}
@media(max-width:700px){.kpi-row{grid-template-columns:1fr}.app-head{display:block}.live-chip{display:inline-block;margin-top:6px}}
</style>
"""
